// Day 13 — the correct implementation plus a family of MUTANTS (subtly broken versions).
// You do not edit this file. You write assertions (in assertions.ts) strong enough to accept the
// correct one and reject every mutant. Run with:  node --test

export type Median = (nums: number[]) => number;

export const correctMedian: Median = (nums) => {
  if (nums.length === 0) throw new Error("median of empty list");
  const s = [...nums].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  if (s.length % 2 === 1) return s[mid];
  return (s[mid - 1] + s[mid]) / 2;
};

export const mutants: { name: string; impl: Median }[] = [
  {
    name: "does-not-sort",
    impl: (nums) => {
      if (nums.length === 0) throw new Error("empty");
      const mid = Math.floor(nums.length / 2);
      if (nums.length % 2 === 1) return nums[mid];
      return (nums[mid - 1] + nums[mid]) / 2;
    },
  },
  {
    name: "returns-mean-not-median",
    impl: (nums) => {
      if (nums.length === 0) throw new Error("empty");
      return nums.reduce((a, b) => a + b, 0) / nums.length;
    },
  },
  {
    name: "even-returns-upper-not-average",
    impl: (nums) => {
      if (nums.length === 0) throw new Error("empty");
      const s = [...nums].sort((a, b) => a - b);
      const mid = Math.floor(s.length / 2);
      if (s.length % 2 === 1) return s[mid];
      return s[mid]; // should be (s[mid - 1] + s[mid]) / 2
    },
  },
  {
    name: "odd-off-by-one",
    impl: (nums) => {
      if (nums.length === 0) throw new Error("empty");
      const s = [...nums].sort((a, b) => a - b);
      const mid = Math.floor(s.length / 2);
      if (s.length % 2 === 1) return s[mid - 1]; // should be s[mid]
      return (s[mid - 1] + s[mid]) / 2;
    },
  },
  {
    name: "empty-returns-zero",
    impl: (nums) => {
      if (nums.length === 0) return 0; // should throw
      const s = [...nums].sort((a, b) => a - b);
      const mid = Math.floor(s.length / 2);
      if (s.length % 2 === 1) return s[mid];
      return (s[mid - 1] + s[mid]) / 2;
    },
  },
];
